python
def xorRegisterPositiveProofStrip(readings, k):
    a=readings
    out=[]
    state=0
    for x in a:
        state^=x
        out.append(state)
    return [x for x in out if x>0]


java
class Solution {
  public int[] xorRegisterPositiveProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
